#!/usr/bin/env python3
import argparse
import os
import subprocess
import sysconfig
from pathlib import Path

import numpy as np
import torch
from jinja2 import Template

from models.quantized_qwen3.air_runtime import compile_runtime
from models.quantized_qwen3.run_attention_core import run_attention_core_on_npu
from models.quantized_qwen3.stages.attention import (
    compile_attention_core_object,
    reference_attention_core,
)


ASYNC_MULTI_HEAD_TEMPLATE = Template(
    """// Generated by mega_spike4_attention_multi_head.py.
module {
  air.channel @attention_q []
  air.channel @attention_kv []
  air.channel @attention_output []

  func.func private @attention_core_tile(
      memref<3xi32, 2 : i32>,
      memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
      memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
      memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
      memref<{{ query_tile_rows }}xf32, 2 : i32>,
      memref<{{ query_tile_rows }}xf32, 2 : i32>,
      memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>)
      attributes {link_with = "attention_core.o", llvm.emit_c_interface}

  func.func @run_attention_core(
      %q: memref<{{ sequence_length }}x{{ q_total_dim }}xf32>,
      %k: memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>,
      %v: memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>,
      %output: memref<{{ sequence_length }}x{{ q_total_dim }}xf32>) {
    %idx1 = arith.constant 1 : index

    %launch_done = air.launch async (%launch_i) in (%launch_s_i=%idx1)
        args(%launch_q=%q, %launch_k=%k, %launch_v=%v, %launch_output=%output)
        : memref<{{ sequence_length }}x{{ q_total_dim }}xf32>,
          memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>,
          memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>,
          memref<{{ sequence_length }}x{{ q_total_dim }}xf32> {
      %l0 = arith.constant 0 : index
      %l1 = arith.constant 1 : index
      %lq = arith.constant {{ query_tile_rows }} : index
      %lkv = arith.constant {{ key_tile_rows }} : index
      %lseq = arith.constant {{ sequence_length }} : index
      %lhead = arith.constant {{ head_dim }} : index
      %lqtotal = arith.constant {{ q_total_dim }} : index
      %lkvtotal = arith.constant {{ kv_total_dim }} : index
      %launch_start = air.wait_all async

{% for head in range(q_heads) %}
{% set input_token = "%launch_start" if head == 0 else "%host_done_" ~ (head - 1) %}
      %q_col_{{ head }} = arith.constant {{ head * head_dim }} : index
      %kv_col_{{ head }} = arith.constant {{ (head // q_heads_per_kv_head) * head_dim }} : index
      %host_done_{{ head }} = scf.for %q_block_{{ head }} = %l0 to %lseq step %lq
          iter_args(%q_token = {{ input_token }}) -> (!air.async.token) {
          %q_put_{{ head }} = air.channel.put async [%q_token] @attention_q[]
              (%launch_q[%q_block_{{ head }}, %q_col_{{ head }}]
               [%lq, %lhead] [%lqtotal, %l1])
              : (memref<{{ sequence_length }}x{{ q_total_dim }}xf32>)
          %kv_done_{{ head }} = scf.for %kv_block_{{ head }} = %l0 to %lseq step %lkv
              iter_args(%kv_token = %q_put_{{ head }}) -> (!air.async.token) {
            %k_put_{{ head }} = air.channel.put async [%kv_token] @attention_kv[]
                (%launch_k[%kv_block_{{ head }}, %kv_col_{{ head }}]
                 [%lkv, %lhead] [%lkvtotal, %l1])
                : (memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>)
            %v_put_{{ head }} = air.channel.put async [%k_put_{{ head }}] @attention_kv[]
                (%launch_v[%kv_block_{{ head }}, %kv_col_{{ head }}]
                 [%lkv, %lhead] [%lkvtotal, %l1])
                : (memref<{{ sequence_length }}x{{ kv_total_dim }}xf32>)
            scf.yield %v_put_{{ head }} : !air.async.token
          }
          %host_output_ready_{{ head }} = air.wait_all async [%q_token, %kv_done_{{ head }}]
          %output_get_{{ head }} = air.channel.get async [%host_output_ready_{{ head }}]
              @attention_output[]
              (%launch_output[%q_block_{{ head }}, %q_col_{{ head }}]
               [%lq, %lhead] [%lqtotal, %l1])
              : (memref<{{ sequence_length }}x{{ q_total_dim }}xf32>)
          scf.yield %output_get_{{ head }} : !air.async.token
        }
{% endfor %}

      %segment_done = air.segment @attention_core_segment async {
        %seg_rows = arith.constant 1 : index
        %seg_cols = arith.constant 1 : index
        %herd_done = air.herd @attention_core_herd async tile (%tile_i, %tile_j)
            in (%herd_s_i=%seg_rows, %herd_s_j=%seg_cols) {
          %h0 = arith.constant 0 : index
          %h1 = arith.constant 1 : index
          %h2 = arith.constant 2 : index
          %hseq = arith.constant {{ sequence_length }} : index
          %hq = arith.constant {{ query_tile_rows }} : index
          %hkv = arith.constant {{ key_tile_rows }} : index
          %hheads = arith.constant {{ q_heads }} : index

          %meta_alloc, %meta_l1 = air.execute -> (memref<3xi32, 2 : i32>) {
            %alloc = memref.alloc() : memref<3xi32, 2 : i32>
            air.execute_terminator %alloc : memref<3xi32, 2 : i32>
          }
          %q_alloc, %q_l1 = air.execute
              -> (memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>) {
            %alloc = memref.alloc()
                : memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
            air.execute_terminator %alloc
                : memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
          }
          %k_alloc, %k_l1 = air.execute
              -> (memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>) {
            %alloc = memref.alloc()
                : memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
            air.execute_terminator %alloc
                : memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
          }
          %v_alloc, %v_l1 = air.execute
              -> (memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>) {
            %alloc = memref.alloc()
                : memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
            air.execute_terminator %alloc
                : memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
          }
          %row_max_alloc, %row_max_l1 = air.execute
              -> (memref<{{ query_tile_rows }}xf32, 2 : i32>) {
            %alloc = memref.alloc() : memref<{{ query_tile_rows }}xf32, 2 : i32>
            air.execute_terminator %alloc : memref<{{ query_tile_rows }}xf32, 2 : i32>
          }
          %row_sum_alloc, %row_sum_l1 = air.execute
              -> (memref<{{ query_tile_rows }}xf32, 2 : i32>) {
            %alloc = memref.alloc() : memref<{{ query_tile_rows }}xf32, 2 : i32>
            air.execute_terminator %alloc : memref<{{ query_tile_rows }}xf32, 2 : i32>
          }
          %out_alloc, %out_l1 = air.execute
              -> (memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>) {
            %alloc = memref.alloc()
                : memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
            air.execute_terminator %alloc
                : memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>
          }

          %alloc_done_raw = air.wait_all async [
              %meta_alloc, %q_alloc, %k_alloc, %v_alloc,
              %row_max_alloc, %row_sum_alloc, %out_alloc]
          %alloc_done = air.wait_all async [%alloc_done_raw]
          %core_heads_done = scf.for %head = %h0 to %hheads step %h1
              iter_args(%head_token = %alloc_done) -> (!air.async.token) {
            %core_done = scf.for %q_block = %h0 to %hseq step %hq
                iter_args(%q_token = %head_token) -> (!air.async.token) {
              %q_block_i32 = arith.index_cast %q_block : index to i32
              %store_q_base = air.execute [%q_token] {
                memref.store %q_block_i32, %meta_l1[%h0] : memref<3xi32, 2 : i32>
              }
              %q_get = air.channel.get async [%store_q_base] @attention_q[]
                  (%q_l1[] [] [])
                  : (memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>)
              %q_ready = air.wait_all async [%store_q_base, %q_get]

              %kv_done = scf.for %kv_block = %h0 to %hseq step %hkv
                  iter_args(%kv_token = %q_ready) -> (!air.async.token) {
                %kv_block_i32 = arith.index_cast %kv_block : index to i32
                %store_kv_base = air.execute [%kv_token] {
                  memref.store %kv_block_i32, %meta_l1[%h1] : memref<3xi32, 2 : i32>
                }
                %k_get = air.channel.get async [%store_kv_base] @attention_kv[]
                    (%k_l1[] [] [])
                    : (memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>)
                %v_get = air.channel.get async [%k_get] @attention_kv[]
                    (%v_l1[] [] [])
                    : (memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>)
                %kv_ready = air.wait_all async [%store_kv_base, %k_get, %v_get]

                %rows_done = scf.for %q_inner = %h0 to %hq step %h1
                    iter_args(%row_token = %kv_ready) -> (!air.async.token) {
                  %q_inner_i32 = arith.index_cast %q_inner : index to i32
                  %store_q_inner = air.execute [%row_token] {
                    memref.store %q_inner_i32, %meta_l1[%h2] : memref<3xi32, 2 : i32>
                  }
                  %call_done = air.execute [%store_q_inner] {
                    func.call @attention_core_tile(
                        %meta_l1, %q_l1, %k_l1, %v_l1,
                        %row_max_l1, %row_sum_l1, %out_l1)
                        : (memref<3xi32, 2 : i32>,
                           memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
                           memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
                           memref<{{ key_tile_rows }}x{{ head_dim }}xf32, 2 : i32>,
                           memref<{{ query_tile_rows }}xf32, 2 : i32>,
                           memref<{{ query_tile_rows }}xf32, 2 : i32>,
                           memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>) -> ()
                  }
                  scf.yield %call_done : !air.async.token
                }
                scf.yield %rows_done : !air.async.token
              }

              %output_ready = air.wait_all async [%q_token, %kv_done]
              %output_put = air.channel.put async [%output_ready] @attention_output[]
                  (%out_l1[] [] [])
                  : (memref<{{ query_tile_rows }}x{{ head_dim }}xf32, 2 : i32>)
              scf.yield %output_put : !air.async.token
            }
            scf.yield %core_done : !air.async.token
          }

          %done = air.wait_all async [%core_heads_done]
        }
      }
    }

    return
  }
}
"""
)


def prepend_air_tool_paths() -> tuple[Path, Path, Path]:
    site_packages = Path(sysconfig.get_paths()["purelib"])
    mlir_air = Path(os.environ.get("MLIR_AIR_INSTALL_DIR", site_packages / "mlir_air"))
    mlir_aie = Path(os.environ.get("MLIR_AIE_INSTALL_DIR", site_packages / "mlir_aie"))
    peano = Path(os.environ.get("PEANO_INSTALL_DIR", site_packages / "llvm-aie"))
    paths = [mlir_air / "bin", mlir_aie / "bin", peano / "bin"]
    os.environ["PATH"] = ":".join(str(path) for path in paths) + ":" + os.environ.get("PATH", "")
    os.environ["MLIR_AIR_INSTALL_DIR"] = str(mlir_air)
    os.environ["MLIR_AIE_INSTALL_DIR"] = str(mlir_aie)
    os.environ["PEANO_INSTALL_DIR"] = str(peano)
    os.environ.setdefault("XRT_HACK_UNSECURE_LOADING_XCLBIN", "1")
    return mlir_air, mlir_aie, peano


def render_module(
    *,
    sequence_length: int,
    head_dim: int,
    query_tile_rows: int,
    key_tile_rows: int,
    q_heads: int,
    kv_heads: int,
) -> str:
    return ASYNC_MULTI_HEAD_TEMPLATE.render(
        sequence_length=sequence_length,
        head_dim=head_dim,
        query_tile_rows=query_tile_rows,
        key_tile_rows=key_tile_rows,
        q_heads=q_heads,
        kv_heads=kv_heads,
        q_heads_per_kv_head=q_heads // kv_heads,
        q_total_dim=q_heads * head_dim,
        kv_total_dim=kv_heads * head_dim,
    )


def lower_async_air_to_aie(source_mlir: Path, work_dir: Path) -> Path:
    air_opt = Path(os.environ["MLIR_AIR_INSTALL_DIR"]) / "bin" / "air-opt"
    channel_mlir = work_dir / "run_attention_core.channel.mlir"
    aie_mlir = work_dir / "run_attention_core.aie.mlir"
    subprocess.run(
        [
            str(air_opt),
            str(source_mlir),
            "--canonicalize",
            "--cse",
            "--air-place-herds=num-rows=1 num-cols=1 row-anchor=2 col-anchor=0",
            "-o",
            str(channel_mlir),
        ],
        check=True,
    )
    subprocess.run(
        [
            str(air_opt),
            str(channel_mlir),
            "--air-to-aie=device=npu2_4col row-offset=2 col-offset=0 stack-size=4096 "
            "emit-while-loop=true",
            "--canonicalize",
            "--cse",
            "-o",
            str(aie_mlir),
        ],
        check=True,
    )
    return aie_mlir


def deterministic_tensor(*, rows: int, cols: int, seed: int, scale: float) -> torch.Tensor:
    if not torch.cuda.is_available():
        raise RuntimeError("PyTorch ROCm device is required for the reference.")
    device = torch.device("cuda")
    generator = torch.Generator(device=device)
    generator.manual_seed(seed)
    return torch.randn((rows, cols), device=device, generator=generator) * scale


def main() -> int:
    parser = argparse.ArgumentParser(description="Spike 4: serial multi-head attention xclbin.")
    parser.add_argument("--sequence-length", type=int, default=16)
    parser.add_argument("--head-dim", type=int, default=128)
    parser.add_argument("--query-tile-rows", type=int, default=4)
    parser.add_argument("--key-tile-rows", type=int, default=4)
    parser.add_argument("--q-heads", type=int, default=2)
    parser.add_argument("--kv-heads", type=int, default=1)
    parser.add_argument("--seed", type=int, default=1)
    parser.add_argument("--scale", type=float, default=0.25)
    parser.add_argument("--warmup", type=int, default=0)
    parser.add_argument("--iterations", type=int, default=1)
    parser.add_argument("--rtol", type=float, default=1e-2)
    parser.add_argument("--atol", type=float, default=1e-2)
    parser.add_argument(
        "--work-dir",
        type=Path,
        default=Path(".cache/npu-spikes/mega-spike4-attention-multi-head"),
    )
    args = parser.parse_args()

    if args.head_dim != 128:
        raise ValueError("attention_core currently targets head_dim=128")
    if args.sequence_length % args.query_tile_rows != 0:
        raise ValueError("query_tile_rows must divide sequence_length")
    if args.sequence_length % args.key_tile_rows != 0:
        raise ValueError("key_tile_rows must divide sequence_length")
    if args.key_tile_rows > 8:
        raise ValueError("attention_core currently validates key_tile_rows up to 8")
    if args.q_heads <= 0 or args.kv_heads <= 0 or args.q_heads % args.kv_heads != 0:
        raise ValueError("q_heads must be a positive multiple of kv_heads")

    _, _, peano = prepend_air_tool_paths()
    args.work_dir = args.work_dir.resolve()
    args.work_dir.mkdir(parents=True, exist_ok=True)

    source_mlir = args.work_dir / "source.air.mlir"
    source_mlir.write_text(
        render_module(
            sequence_length=args.sequence_length,
            head_dim=args.head_dim,
            query_tile_rows=args.query_tile_rows,
            key_tile_rows=args.key_tile_rows,
            q_heads=args.q_heads,
            kv_heads=args.kv_heads,
        )
    )
    aie_mlir = lower_async_air_to_aie(source_mlir, args.work_dir)

    object_path = compile_attention_core_object(
        work_dir=args.work_dir / "objects",
        peano_install_dir=str(peano),
        head_dim=args.head_dim,
        sequence_length=args.sequence_length,
        query_tile_rows=args.query_tile_rows,
        key_tile_rows=args.key_tile_rows,
    )
    _, xclbin, insts = compile_runtime(
        aie_mlir=aie_mlir,
        work_dir=args.work_dir,
        instance_name="run_attention_core",
        peano_install_dir=str(peano),
        link_objects=(object_path,),
    )

    q_ref = deterministic_tensor(
        rows=args.sequence_length,
        cols=args.q_heads * args.head_dim,
        seed=args.seed,
        scale=args.scale,
    )
    k_ref = deterministic_tensor(
        rows=args.sequence_length,
        cols=args.kv_heads * args.head_dim,
        seed=args.seed + 1,
        scale=args.scale,
    )
    v_ref = deterministic_tensor(
        rows=args.sequence_length,
        cols=args.kv_heads * args.head_dim,
        seed=args.seed + 2,
        scale=0.25,
    )
    expected = reference_attention_core(
        q=q_ref,
        k=k_ref,
        v=v_ref,
        q_heads=args.q_heads,
        kv_heads=args.kv_heads,
    )
    q = np.ascontiguousarray(q_ref.detach().cpu().numpy())
    k = np.ascontiguousarray(k_ref.detach().cpu().numpy())
    v = np.ascontiguousarray(v_ref.detach().cpu().numpy())
    output = np.zeros(tuple(expected.shape), dtype=np.float32)

    actual, latencies_ms = run_attention_core_on_npu(
        xclbins=[xclbin],
        insts_paths=[insts],
        q=q,
        k=k,
        v=v,
        output=output,
        expected=expected,
        warmup=args.warmup,
        iterations=args.iterations,
        rtol=args.rtol,
        atol=args.atol,
    )

    print(f"reference_device {torch.cuda.get_device_name(0)}")
    print(f"xclbin {xclbin}")
    print(f"insts {insts}")
    print(f"first8 {actual.reshape(-1)[:8].tolist()}")
    print(f"mean_ms {sum(latencies_ms) / len(latencies_ms):.3f}")
    print(f"work_dir {args.work_dir}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
